# ANCIENT RUINS — History, Math, Engineering
# ============================================================================
def ancient_ruins():
    Q = []
    Q.append(_q('pyramid-geometry', 'Pyramid Geometry', ['math.geometry', 'history.ancient-civilizations'], 22, 'The Ancient Ruins contain pyramid structures whose geometry reveals precise mathematical knowledge.', [_s('measure', 'Measure the base length and height of a stone pyramid in the ruins.', 'Record each dimension carefully using the measuring tools.'), _s('solve', 'Calculate the volume using V = (1/3) times base area times height.', 'Base area of a square pyramid = side length squared.'), _s('solve', 'Calculate the slant height using the Pythagorean theorem.', 'The slant height, half-base, and pyramid height form a right triangle.'), _s('compare', 'Compare the pyramid proportions to known mathematical ratios like phi and pi.', 'Many ancient pyramids encode mathematical constants in their proportions.')]))
    Q.append(_q('arch-engineering', 'Ancient Arch Design', ['engineering.structural-analysis', 'physics.forces'], 22, 'Stone arches in the ruins have survived millennia and their structural principles need analysis.', [_s('observe', 'Examine how the arch stones are arranged and identify the keystone.', 'The keystone at the top locks all other stones in place.'), _s('solve', 'Analyze the forces in the arch: each stone redirects the load sideways and downward.', 'Compression forces flow through the arch to the foundations.'), _s('build', 'Construct a model arch from blocks to demonstrate how it supports weight.', 'Start from both sides and meet at the keystone in the center.'), _s('experiment', 'Test the arch with loads and compare to a flat beam of the same materials.', 'The arch should support significantly more weight than the beam.')]))
    Q.append(_q('aqueduct-flow', 'Aqueduct Water Flow', ['physics.forces', 'math.equations'], 22, 'The ruins contain an ancient aqueduct system whose water flow engineering needs study.', [_s('measure', 'Measure the slope of the aqueduct channel at different sections.', 'A slight downward slope keeps water flowing by gravity.'), _s('solve', 'Calculate the flow rate based on channel cross-section and water velocity.', 'Flow rate = cross-sectional area times velocity.'), _s('compare', 'Compare the ancient aqueduct slope to modern civil engineering standards.', 'Modern systems use about 1 cm drop per 10 meters of distance.'), _s('design', 'Design a repair for a damaged aqueduct section that maintains the correct slope.', 'The new section must match the slope of the intact portions.')]))
    Q.append(_q('ancient-number-systems', 'Number System Archaeology', ['math.patterns', 'history.ancient-civilizations'], 20, 'Inscriptions in the ruins use ancient number systems that need decoding and comparison.', [_s('decode', 'Identify the symbols used for numbers in the ruins inscriptions.', 'Look for repeated symbols that might represent 1, 5, 10, etc.'), _s('compare', 'Compare the ancient number system to Roman numerals and our decimal system.', 'Is it base-10, base-60, base-20, or some other base?'), _s('solve', 'Convert numbers between the ancient system and modern decimal notation.', 'Understand the place value system the ancients used.'), _s('pattern', 'Identify mathematical operations inscribed on the walls.', 'Look for equations showing addition, multiplication, or division.')]))
    Q.append(_q('mosaic-patterns', 'Mosaic Geometry Analysis', ['math.geometry', 'math.patterns'], 20, 'Floor mosaics in the ruins display complex geometric patterns that encode mathematical principles.', [_s('observe', 'Identify all the geometric shapes used in the mosaic pattern.', 'Look for triangles, squares, hexagons, and other regular polygons.'), _s('measure', 'Measure the angles and side lengths of the repeating pattern unit.', 'The repeating unit tiles the floor without gaps.'), _s('solve', 'Calculate the area of the repeating unit and the total mosaic area.', 'Count how many units fit in the floor and multiply by unit area.'), _s('design', 'Create a new mosaic design using the same geometric principles.', 'Choose shapes whose angles sum correctly at each vertex point.')]))
    Q.append(_q('sundial-time', 'Sundial Time Measurement', ['physics.optics', 'math.geometry'], 20, 'An ancient sundial in the ruins tells time using shadow angles that need calibration.', [_s('observe', 'Track the shadow position on the sundial at hourly intervals.', 'Note how the shadow angle changes as time passes.'), _s('measure', 'Measure the angle between each hour mark on the sundial face.', 'Equal time intervals should correspond to equal angle changes.'), _s('solve', 'Calculate the expected shadow angle at a specific time using geometry.', 'The shadow angle depends on the sun position and sundial latitude.'), _s('predict', 'Predict the time from the shadow angle without a clock.', 'Use the measured angle-to-time relationship.')]))
    Q.append(_q('ancient-metallurgy', 'Ancient Metal Analysis', ['chemistry.elements', 'engineering.materials-science'], 22, 'Metal artifacts in the ruins show advanced metallurgy techniques that predate modern methods.', [_s('measure', 'Test the hardness and density of three ancient metal artifacts.', 'Use standard material testing procedures.'), _s('experiment', 'Perform simple chemical tests to identify the metals and alloys used.', 'Flame tests and acid reactivity narrow down the composition.'), _s('compare', 'Compare ancient alloy compositions to modern equivalents.', 'Many ancient alloys closely resemble modern formulations.'), _s('solve', 'Calculate the ratio of metals in each alloy from the test results.', 'Express composition as percentages of each component.')]))
    Q.append(_q('ruins-coordinates', 'Ruin Site Coordinate Grid', ['math.coordinate-geometry', 'history.ancient-civilizations'], 18, 'The archaeological site needs a coordinate grid system for mapping artifact locations.', [_s('design', 'Establish a coordinate system with the main temple entrance as origin.', 'Align axes with the major and minor axes of the temple.'), _s('place', 'Mark artifact locations on the coordinate grid as they are discovered.', 'Record x and y coordinates for each artifact.'), _s('solve', 'Calculate distances between significant artifact clusters.', 'Use the distance formula for each pair of clusters.'), _s('predict', 'Identify likely locations of undiscovered artifacts based on the pattern of finds.', 'Look for symmetry or regular spacing in the artifact distribution.')]))
    Q.append(_q('proportion-scale-ruins', 'Ruins Proportion Analysis', ['math.proportions', 'math.ratios'], 18, 'Ancient buildings follow precise proportional systems that need documentation.', [_s('measure', 'Measure the width, height, and depth of doorways, windows, and columns.', 'Record all three dimensions for each architectural element.'), _s('solve', 'Calculate the ratio of height to width for each element.', 'Express ratios in simplest form.'), _s('pattern', 'Identify which proportional ratio the ancient builders used most consistently.', 'Common ancient ratios include 3:2, 5:3, and the golden ratio 1.618:1.'), _s('compare', 'Compare the ancient proportional system to modern architectural standards.', 'Many modern buildings still use classical proportional systems.')]))
    Q.append(_q('roman-road', 'Roman Road Engineering', ['engineering.structural-analysis', 'engineering.materials-science'], 22, 'A section of ancient road has survived centuries and its layered construction needs study.', [_s('observe', 'Examine the cross-section of the ancient road and identify its construction layers.', 'Look for distinct layers of different materials from bottom to top.'), _s('measure', 'Measure the thickness of each road layer and the overall road profile.', 'Note the crown (slight center hump) that aids drainage.'), _s('compare', 'Compare the ancient road construction to modern road building techniques.', 'Both use layered construction with drainage, but materials differ.'), _s('design', 'Design a road repair using the same layered principles with modern materials.', 'Maintain the layered structure and drainage profile of the original.')]))
    Q.append(_q('pi-discovery', 'Rediscovering Pi', ['math.geometry', 'history.ancient-civilizations'], 20, 'Circular structures in the ruins reveal how the ancients calculated pi.', [_s('measure', 'Measure the circumference and diameter of three circular structures.', 'Use a flexible measuring line for circumference and rigid tool for diameter.'), _s('solve', 'Calculate circumference divided by diameter for each circle.', 'This ratio should be approximately 3.14159 for every circle.'), _s('compare', 'Compare your calculated pi values to known ancient approximations.', 'Babylonians used 3.125; Egyptians used 3.1605; Archimedes found 3.1416.'), _s('solve', 'Use pi to calculate the area of the largest circular platform.', 'Area = pi times radius squared.')]))
    Q.append(_q('ancient-agriculture', 'Ancient Farming Methods', ['biology.ecosystems', 'history.ancient-civilizations'], 20, 'Terraced farm plots in the ruins show ancient agricultural knowledge that needs analysis.', [_s('observe', 'Examine the terracing system and identify how it manages water and soil.', 'Terraces create flat growing surfaces on slopes.'), _s('measure', 'Measure the terrace dimensions and calculate the total growing area.', 'Each terrace is a rectangle; sum all areas for the total.'), _s('compare', 'Compare crop yields from terraced vs un-terraced test plots.', 'Terracing reduces erosion and improves water retention.'), _s('predict', 'Predict how many people the terraced system could feed based on crop yields.', 'Calculate total production and divide by per-person food requirements.')]))
    Q.append(_q('writing-systems', 'Ancient Writing Decipherment', ['history.ancient-civilizations', 'cs.algorithms'], 22, 'Inscriptions on the ruin walls use an unknown writing system that needs systematic decoding.', [_s('observe', 'Catalog all unique symbols found in the inscriptions.', 'Count the total number of distinct symbols used.'), _s('count', 'Perform frequency analysis on the symbols across multiple inscriptions.', 'The most common symbols likely represent common sounds or words.'), _s('decode', 'Use known bilingual inscriptions to map ancient symbols to known words.', 'Compare the ancient text to any parallel text in a known language.'), _s('pattern', 'Identify grammatical patterns like word order and sentence structure.', 'Look for consistent symbol groupings that suggest phrases.')]))
    Q.append(_q('golden-ratio', 'Golden Ratio in Architecture', ['math.ratios', 'math.geometry'], 20, 'Temple proportions in the ruins consistently use the golden ratio in their design.', [_s('measure', 'Measure the length and width of the temple front facade.', 'Record precise measurements of the overall dimensions.'), _s('solve', 'Calculate the ratio of length to width and compare to the golden ratio 1.618.', 'Divide the longer dimension by the shorter one.'), _s('find', 'Locate three more examples of the golden ratio in the ruins architecture.', 'Look at window proportions, column spacing, and room dimensions.'), _s('design', 'Design a new structure using the golden ratio for its major proportions.', 'Make the length 1.618 times the width for each rectangular element.')]))
    Q.append(_q('simple-machines-ruins', 'Ancient Construction Machines', ['physics.simple-machines', 'engineering.mechanisms'], 22, 'Evidence in the ruins shows how simple machines were used to build massive structures.', [_s('observe', 'Identify marks and grooves that indicate use of ramps, levers, and pulleys.', 'Look for wear patterns on stone surfaces.'), _s('solve', 'Calculate the force needed to move a 5000 kg stone block up a ramp.', 'Force = weight times sin(angle) for an ideal ramp.'), _s('compare', 'Compare the labor required with ramps vs levers vs pulleys.', 'Each simple machine trades force for distance differently.'), _s('design', 'Plan how to move a large stone using only the tools available to ancient builders.', 'Combine multiple simple machines for the best mechanical advantage.')]))
    Q.append(_q('area-excavation', 'Excavation Area Calculations', ['math.area-volume', 'math.geometry'], 18, 'The excavation site needs careful area and volume calculations for removal planning.', [_s('measure', 'Measure the irregular boundaries of the excavation zone.', 'Break the irregular shape into rectangles and triangles.'), _s('solve', 'Calculate the total area by summing the component shape areas.', 'Area of triangle = 1/2 base times height; rectangle = length times width.'), _s('solve', 'Calculate the volume of soil to remove at a depth of 2 meters.', 'Volume = area times depth.'), _s('predict', 'Estimate the number of cart loads needed based on cart capacity.', 'Divide total volume by the volume each cart can hold.')]))
    Q.append(_q('pythagorean-ruins', 'Pythagorean Triples in Ruins', ['math.pythagorean-theorem', 'history.ancient-civilizations'], 20, 'The ancients used Pythagorean triples for precise right angles in construction.', [_s('observe', 'Find right angles in the ruins and measure the sides of the triangle formed.', 'Ancient builders often used 3-4-5 or 5-12-13 triangles.'), _s('solve', 'Verify the Pythagorean theorem: a^2 + b^2 = c^2 for each measured triangle.', '3^2 + 4^2 = 9 + 16 = 25 = 5^2 confirms the 3-4-5 triple.'), _s('build', 'Use a knotted rope with 12 equal segments to form a 3-4-5 right triangle.', 'Mark 3, 4, and 5 segments and pull into a triangle shape.'), _s('experiment', 'Verify the right angle with a modern level tool.', 'The corner formed by the 3 and 4 sides should be exactly 90 degrees.')]))
    Q.append(_q('dating-artifacts', 'Artifact Dating Methods', ['math.equations', 'history.ancient-civilizations'], 20, 'Archaeological artifacts need age estimation using mathematical dating techniques.', [_s('measure', 'Count growth rings in petrified wood samples from different ruin levels.', 'Each ring typically represents one year of growth.'), _s('solve', 'Calculate the age of each sample from the ring count.', 'Total rings equals total years of growth.'), _s('compare', 'Compare dating estimates from different methods and check for consistency.', 'Multiple independent methods should give similar ages.'), _s('predict', 'Estimate the age of a deeper ruin layer based on the pattern of dated layers above.', 'Deeper layers are older; use the rate of accumulation to extrapolate.')]))
    Q.append(_q('statistics-artifacts', 'Artifact Statistics', ['math.statistics', 'history.ancient-civilizations'], 18, 'Artifact measurements from the site need statistical analysis for classification.', [_s('collect', 'Measure the dimensions of 20 pottery fragments from the excavation.', 'Record diameter, thickness, and weight for each fragment.'), _s('solve', 'Calculate mean, median, and range for each measurement category.', 'These statistics summarize the typical artifact properties.'), _s('compare', 'Determine if the fragments come from one pot type or multiple types.', 'Multiple types would show a bimodal distribution.'), _s('predict', 'Estimate the original pot size from the fragment measurements.', 'Use the curvature of fragments to estimate the complete diameter.')]))
    Q.append(_q('percentage-excavation', 'Excavation Progress Tracking', ['math.percentages', 'math.area-volume'], 18, 'Excavation progress must be tracked as a percentage of the total site.', [_s('measure', 'Calculate the total area of the excavation site.', 'Use the site map and coordinate grid measurements.'), _s('solve', 'Calculate the area excavated so far and express as a percentage of total.', 'Percentage = (excavated area / total area) times 100.'), _s('solve', 'Calculate what percentage of the estimated artifacts has been found.', 'Compare found artifacts to the estimated total based on density sampling.'), _s('predict', 'Estimate the completion date based on current excavation rate.', 'Remaining area divided by daily area rate gives days remaining.')]))
    Q.append(_q('coding-artifact-catalog', 'Artifact Database', ['cs.data-structures', 'cs.functions'], 20, 'Discovered artifacts need a searchable digital catalog for research access.', [_s('code', 'Design a data structure for artifact records with location, type, date, and description.', 'Each record needs fields for all important artifact attributes.'), _s('code', 'Write functions to add, search, and filter artifacts by location or type.', 'The search function should match partial entries.'), _s('code', 'Add a function that generates statistics about the artifact collection.', 'Count artifacts per type, per location, and per date range.'), _s('experiment', 'Load 30 artifact records and test all search and statistics functions.', 'Verify results match manual counting and inspection.')]))
    Q.append(_q('equation-trade-routes', 'Ancient Trade Route Analysis', ['math.equations', 'economics.trade'], 20, 'Trade routes converging at the ruins reveal economic relationships expressible as equations.', [_s('observe', 'Map the trade routes visible in the ruins based on imported goods found.', 'Different goods came from different directions and distances.'), _s('solve', 'Calculate the distance of each trade route from the origin of its goods.', 'Use the coordinate distances between the ruins and known source locations.'), _s('solve', 'Model the relationship between distance and goods quantity as a linear equation.', 'Farther sources should show fewer imported items.'), _s('predict', 'Predict the likely origin of an unidentified trade good based on its abundance.', 'Use the distance-abundance equation to estimate the source distance.')]))
    Q.append(_q('probability-excavation', 'Excavation Discovery Probability', ['math.probability', 'math.statistics'], 18, 'The probability of finding valuable artifacts varies by ruin zone and depth.', [_s('count', 'Record the number of significant finds per 100 soil volumes at different zones.', 'Dig and sieve 100 volumes in each zone and count finds.'), _s('solve', 'Calculate the probability of a significant find per volume in each zone.', 'Probability = finds divided by total volumes examined.'), _s('compare', 'Rank zones by discovery probability to prioritize excavation efforts.', 'Focus resources on the zones with highest probabilities.'), _s('predict', 'Estimate total expected finds for a planned 500-volume dig in the richest zone.', 'Expected finds = probability times planned volume count.')]))
    # Story quests (7)
    Q.append(_q('machine-ruins-gate', 'Machine Fragment: Gateway Mechanism', ['engineering.mechanisms', 'physics.forces'], 22, 'An ancient gateway mechanism responds to specific force combinations that no modern key can replicate.', [_s('observe', 'Document the gateway mechanism and identify all moving parts.', 'Note hinges, locks, levers, and any pressure-sensitive components.'), _s('measure', 'Measure the force required at each input point to activate the mechanism.', 'Use force gauges at each lever and pressure plate.'), _s('solve', 'Determine the correct sequence and force combination to open the gateway.', 'Analyze how the internal mechanisms connect each input to the lock.'), _s('experiment', 'Apply the calculated force combination and observe the gateway response.', 'Make small adjustments if the initial attempt is close but not exact.')], True))
    Q.append(_q('machine-ruins-calendar', 'Machine Fragment: Precision Calendar', ['math.patterns', 'physics.forces'], 22, 'An ancient calendar mechanism tracks celestial cycles with accuracy matching modern computers.', [_s('observe', 'Document the gear trains and indicator dials of the calendar mechanism.', 'Count the teeth on each visible gear and note the dial markings.'), _s('measure', 'Determine the gear ratios and calculate the cycles they represent.', 'Each gear ratio corresponds to an astronomical period.'), _s('decode', 'Identify which celestial cycles each dial tracks: lunar, solar, planetary.', 'Compare the calculated periods to known astronomical cycles.'), _s('compare', 'Compare the mechanism accuracy to modern calendar calculations.', 'Calculate the error per century for each tracked cycle.')], True))
    Q.append(_q('machine-ruins-stone', 'Machine Fragment: Resonant Stone', ['physics.waves', 'chemistry.elements'], 22, 'A stone in the ruins produces a clear musical tone when struck, unlike any natural rock.', [_s('measure', 'Measure the frequency and duration of the tone when the stone is struck.', 'Use sound analysis tools to record the exact frequency.'), _s('experiment', 'Test different striking locations and forces to map the tonal range.', 'Note which areas produce different pitches.'), _s('compare', 'Compare the tone properties to known musical stones and instruments.', 'Some ancient cultures carved stones specifically for musical properties.'), _s('solve', 'Analyze the stone composition and density to explain its acoustic properties.', 'Denser, more uniform materials generally produce clearer tones.')], True))
    Q.append(_q('machine-ruins-light', 'Machine Fragment: Eternal Lamp', ['physics.circuits', 'chemistry.reactions'], 22, 'A lamp in the ruins has apparently been lit continuously for centuries without any fuel source.', [_s('observe', 'Examine the lamp construction and look for any fuel reservoir or energy source.', 'Note the light output, color, and any heat production.'), _s('measure', 'Measure the light output and energy consumption of the lamp.', 'Use light and heat sensors to quantify the energy output.'), _s('experiment', 'Test whether shielding the lamp from air, light, or ground contact affects its output.', 'Isolate potential energy inputs one at a time.'), _s('compare', 'Compare the lamp energy output to the maximum possible from any known chemical reaction.', 'Calculate the energy density implied by the lamp continuous operation.')], True))
    Q.append(_q('machine-ruins-water', 'Machine Fragment: Water Lifter', ['physics.forces', 'engineering.mechanisms'], 22, 'An ancient device lifts water uphill without any visible pump or energy source.', [_s('observe', 'Trace the water path through the ancient device from intake to output.', 'Note any chambers, valves, or moving components along the path.'), _s('measure', 'Measure the height the water is lifted and the flow rate achieved.', 'Calculate the gravitational potential energy gained by the water.'), _s('solve', 'Calculate the minimum power required to lift water at the observed rate and height.', 'Power = mass flow rate times gravity times height.'), _s('compare', 'Compare the device efficiency to modern water pumps.', 'Modern pumps are typically 60-90% efficient at converting energy to water lifting.')], True))
    Q.append(_q('machine-ruins-map-floor', 'Machine Fragment: Living Map', ['math.coordinate-geometry', 'history.ancient-civilizations'], 22, 'A floor mosaic in the ruins shifts and updates to show real-time geographic information.', [_s('observe', 'Document what the living map displays and how it changes over time.', 'Note whether it shows topography, weather, or settlements.'), _s('measure', 'Compare map features to known geographic locations and check accuracy.', 'Identify landmarks on the map and compare to actual positions.'), _s('compare', 'Compare the map resolution and accuracy to modern satellite mapping.', 'Note what details the ancient map captures that modern maps do or do not.'), _s('experiment', 'Test whether the map responds to events by creating a visible change in the mapped area.', 'Make a detectable change and observe if the map updates.')], True))
    Q.append(_q('machine-ruins-alloy', 'Machine Fragment: Unforgeable Metal', ['engineering.materials-science', 'chemistry.elements'], 22, 'Metal components in the ruins cannot be scratched, melted, or deformed by any available tool.', [_s('experiment', 'Attempt to scratch, bend, and heat the ancient metal with Workshop tools.', 'Try the hardest available tools and the hottest forge temperature.'), _s('measure', 'Measure whatever properties are measurable: density, magnetic response, conductivity.', 'Record any property the metal reveals, even if it resists deformation testing.'), _s('compare', 'Compare the measurable properties to known super-strong modern materials.', 'Check against tungsten carbide, tool steel, and ceramic composites.'), _s('solve', 'Estimate the theoretical strength of the ancient metal from its resistance to testing.', 'Calculate the minimum strength needed to resist each failed test attempt.')], True))
    return Q

