    Q.append(_q('load-path', 'Load Path Analysis', ['engineering.structural-analysis', 'physics.forces'], 22, 'A building design needs load path analysis to ensure forces reach the foundation safely.', [_s('observe', 'Trace how a roof load transfers through the structure to the ground.', 'Follow the force from where it is applied through each connecting member.'), _s('solve', 'Calculate the force at each connection point along the load path.', 'Forces must balance at every joint for the structure to be stable.'), _s('diagnose', 'Identify any missing load path connections that could cause failure.', 'Every load must have a continuous path to the foundation.'), _s('repair', 'Add structural members to complete any broken load paths.', 'Connect isolated members to the main structural framework.')]))
    Q.append(_q('beam-deflection', 'Beam Deflection Prediction', ['engineering.structural-analysis', 'math.equations'], 22, 'Floor beams deflect under load and the amount must be predicted to prevent excessive sagging.', [_s('measure', 'Measure the deflection of a beam under five increasing loads.', 'Place the load at the center and measure the sag at that point.'), _s('solve', 'Plot load vs deflection and verify the linear relationship.', 'Deflection should be proportional to load within the elastic range.'), _s('solve', 'Calculate the beam stiffness from the slope of the load-deflection graph.', 'Stiffness = load / deflection in newtons per meter.'), _s('predict', 'Predict whether the beam will sag more than the maximum allowable under full design load.', 'Compare predicted deflection to the maximum allowable value.')]))
    Q.append(_q('floor-plan-area', 'Floor Plan Area Calculations', ['math.area-volume', 'math.geometry'], 20, 'Architectural floor plans need accurate area calculations for material estimation.', [_s('measure', 'Measure each room in the floor plan and classify its shape.', 'Most rooms are rectangles but some may be L-shaped or triangular.'), _s('solve', 'Calculate the area of each room using the appropriate formula.', 'L-shapes can be split into two rectangles.'), _s('solve', 'Sum all room areas plus hallways and walls for the total building footprint.', 'Include wall thickness in the overall footprint calculation.'), _s('solve', 'Calculate the amount of flooring material needed with 10 percent waste factor.', 'Flooring needed = total area times 1.10.')]))
    Q.append(_q('angle-roof-design', 'Roof Angle Design', ['math.geometry', 'engineering.structural-analysis'], 20, 'Roof angles must balance water drainage with structural efficiency and material costs.', [_s('solve', 'Calculate the roof angle needed for a 4 m height rise over a 6 m half-span.', 'Angle = arctan(rise / run) gives the pitch angle.'), _s('compare', 'Compare material needs for low-pitch (15 degree) vs steep (45 degree) roofs.', 'Steeper roofs need longer rafters but shed water and snow better.'), _s('solve', 'Calculate the rafter length for each angle using trigonometry.', 'Rafter length = half-span / cos(angle).'), _s('design', 'Choose the optimal roof angle balancing drainage, material cost, and structural load.', 'Consider local climate conditions when selecting the angle.')]))
    Q.append(_q('pythagorean-diagonal', 'Diagonal Measurements', ['math.pythagorean-theorem', 'engineering.design-process'], 18, 'Room diagonals must be calculated for furniture fitting and square-checking.', [_s('measure', 'Measure the length and width of a rectangular room.', 'Record both dimensions precisely.'), _s('solve', 'Calculate the room diagonal using the Pythagorean theorem.', 'Diagonal = sqrt(length^2 + width^2).'), _s('experiment', 'Measure the actual diagonal and compare to the calculated value.', 'Use a long measuring tape corner to corner.'), _s('solve', 'Use the diagonal calculation to verify the room corners are square.', 'If both diagonals are equal, the rectangle is true.')]))
    Q.append(_q('volume-concrete', 'Concrete Volume Estimation', ['math.area-volume', 'engineering.materials-science'], 20, 'Foundation construction needs precise concrete volume calculations to avoid waste or shortages.', [_s('measure', 'Measure the dimensions of the foundation trench: length, width, and depth.', 'Record all three dimensions in meters.'), _s('solve', 'Calculate the volume of concrete needed in cubic meters.', 'Volume = length times width times depth.'), _s('solve', 'Add 5 percent extra for waste and spillage.', 'Total order = calculated volume times 1.05.'), _s('solve', 'Calculate the number of concrete mixer loads needed given 0.8 cubic meters per load.', 'Divide total volume by load capacity and round up.')]))
    Q.append(_q('scale-model', 'Architectural Scale Model', ['math.proportions', 'math.ratios'], 20, 'A scale model of the building design must be constructed for review.', [_s('solve', 'Choose a scale factor that makes the model a manageable size.', 'A 1:50 scale makes a 10 m building become a 20 cm model.'), _s('solve', 'Convert all building dimensions to model dimensions using the scale.', 'Multiply each real measurement by the scale factor.'), _s('build', 'Construct the scale model using the calculated dimensions.', 'Cut each piece to the scaled size before assembly.'), _s('solve', 'Calculate the model volume and compare to real building volume.', 'Volume scales by the cube of the linear scale factor.')]))
    Q.append(_q('symmetry-design', 'Architectural Symmetry', ['math.geometry', 'engineering.design-process'], 18, 'Building facades use symmetry principles that need mathematical analysis.', [_s('observe', 'Identify all lines and points of symmetry in three building facades.', 'Bilateral symmetry has one mirror line; higher symmetry has more.'), _s('measure', 'Verify symmetry by comparing dimensions on opposite sides of each axis.', 'Corresponding elements should have equal dimensions.'), _s('design', 'Create a new facade design with exactly two lines of symmetry.', 'Both vertical and horizontal symmetry require careful planning.'), _s('compare', 'Compare symmetric vs asymmetric designs for visual appeal and structural efficiency.', 'Symmetric structures often distribute loads more evenly.')]))
    Q.append(_q('material-strength', 'Material Strength Testing', ['engineering.materials-science', 'math.equations'], 22, 'Three building materials need strength testing to determine which is best for each application.', [_s('experiment', 'Apply increasing force to samples of wood, stone, and metal until they fail.', 'Record the force at which each material breaks or permanently deforms.'), _s('solve', 'Calculate the stress at failure: stress = force / cross-sectional area.', 'Stress is measured in pascals (newtons per square meter).'), _s('compare', 'Rank the materials by tensile strength, compressive strength, and cost.', 'The best material depends on the type of loading expected.'), _s('design', 'Specify which material to use for beams (tension), columns (compression), and walls.', 'Match each structural role to the material strongest in that loading type.')]))
    Q.append(_q('truss-types', 'Truss Type Comparison', ['engineering.structural-analysis', 'math.pythagorean-theorem'], 22, 'Different truss designs need comparison to find the most efficient for the current project.', [_s('build', 'Construct models of Pratt, Warren, and Howe trusses at the same scale.', 'Each truss type arranges diagonal members differently.'), _s('experiment', 'Test each truss model under identical loads and measure deflection.', 'Apply the same weight at the center of each truss.'), _s('compare', 'Compare load capacity, weight, and material usage for each truss type.', 'The best truss maximizes strength while minimizing material.'), _s('solve', 'Calculate the forces in key members of the winning truss design.', 'Use force balance at each joint to find member forces.')]))
    Q.append(_q('column-buckling', 'Column Stability Analysis', ['engineering.structural-analysis', 'physics.forces'], 22, 'Tall slender columns can buckle under load and their maximum safe height needs calculation.', [_s('experiment', 'Test columns of different lengths under compression load until they buckle.', 'Start with short columns and progressively test longer ones.'), _s('measure', 'Record the buckling load for each column length.', 'Note the load at which the column suddenly bows sideways.'), _s('solve', 'Plot the relationship between column length and buckling load.', 'Buckling load decreases rapidly as length increases.'), _s('predict', 'Predict the maximum safe height for a column that must support a specific load.', 'Find the length where buckling load equals the required support load.')]))
